#include "windows_user32_input.h"
enum fnv_cpu_result fnv_user32_update_di_snapshot(struct fnv_windows_user32 *u,const struct fnv_di_snapshot *s,int focused){
    static const unsigned char vk[256]={
[0x01]=0x1b,[0x02]=0x31,[0x03]=0x32,[0x04]=0x33,[0x05]=0x34,[0x06]=0x35,[0x07]=0x36,[0x08]=0x37,[0x09]=0x38,[0x0a]=0x39,[0x0b]=0x30,[0x0c]=0xbd,[0x0d]=0xbb,[0x0e]=0x08,[0x0f]=0x09,[0x10]=0x51,[0x11]=0x57,[0x12]=0x45,[0x13]=0x52,[0x14]=0x54,[0x15]=0x59,[0x16]=0x55,[0x17]=0x49,[0x18]=0x4f,[0x19]=0x50,[0x1a]=0xdb,[0x1b]=0xdd,[0x1c]=0x0d,[0x1d]=0xa2,[0x1e]=0x41,[0x1f]=0x53,[0x20]=0x44,[0x21]=0x46,[0x22]=0x47,[0x23]=0x48,[0x24]=0x4a,[0x25]=0x4b,[0x26]=0x4c,[0x27]=0xba,[0x28]=0xde,[0x29]=0xc0,[0x2a]=0xa0,[0x2b]=0xdc,[0x2c]=0x5a,[0x2d]=0x58,[0x2e]=0x43,[0x2f]=0x56,[0x30]=0x42,[0x31]=0x4e,[0x32]=0x4d,[0x33]=0xbc,[0x34]=0xbe,[0x35]=0xbf,[0x36]=0xa1,[0x37]=0x6a,[0x38]=0xa4,[0x39]=0x20,[0x3a]=0x14,[0x3b]=0x70,[0x3c]=0x71,[0x3d]=0x72,[0x3e]=0x73,[0x3f]=0x74,[0x40]=0x75,[0x41]=0x76,[0x42]=0x77,[0x43]=0x78,[0x44]=0x79,[0x45]=0x90,[0x46]=0x91,[0x47]=0x67,[0x48]=0x68,[0x49]=0x69,[0x4a]=0x6d,[0x4b]=0x64,[0x4c]=0x65,[0x4d]=0x66,[0x4e]=0x6b,[0x4f]=0x61,[0x50]=0x62,[0x51]=0x63,[0x52]=0x60,[0x53]=0x6e,[0x56]=0xe2,[0x57]=0x7a,[0x58]=0x7b,[0x9c]=0x0d,[0x9d]=0xa3,[0xb5]=0x6f,[0xb7]=0x2c,[0xb8]=0xa5,[0xc5]=0x13,[0xc7]=0x24,[0xc8]=0x26,[0xc9]=0x21,[0xcb]=0x25,[0xcd]=0x27,[0xcf]=0x23,[0xd0]=0x28,[0xd1]=0x22,[0xd2]=0x2d,[0xd3]=0x2e,[0xdb]=0x5b,[0xdc]=0x5c,[0xdd]=0x5d};
    if(!s || (focused!=0 && focused!=1))return FNV_CPU_INVALID;
    unsigned char keys[256]={0};
    for(unsigned i=0;i<256;i++){
        if(s->keys[i]!=0 && s->keys[i]!=128)return FNV_CPU_INVALID;
        if(s->keys[i]){if(!vk[i])return FNV_CPU_INVALID;keys[vk[i]]=128;}
    }
    static const unsigned char mouse[]={1,2,4,5,6};
    for(unsigned i=0;i<8;i++){
        if(s->buttons[i]!=0 && s->buttons[i]!=128)return FNV_CPU_INVALID;
        if(s->buttons[i]){if(i>=5)return FNV_CPU_INVALID;keys[mouse[i]]=128;}
    }
    return fnv_windows_user32_update_keys(u,keys,focused);
}
